export var EnigmailVerify = {
  _initialized: false,
  lastMsgUri: null,

  init() {
    if (this._initialized) {
      return;
    }
    this._initialized = true;
  },

  setLastMsgUri(msgUriSpec) {
    this.lastMsgUri = msgUriSpec;
  },

  newVerifier(protocol) {
    const v = new MimeVerify(protocol);
    return v;
  },
};
